DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT i.indexname FROM pg_indexes i
    WHERE i.schemaname = 'public' AND i.tablename IN ('invoice', 'customer', 'org', 'user_account', 'ks_membership', 'org', 'user_account') AND i.indexname NOT IN ('user_account_email_uniq', 'customer_owner', 'customer_email_uniq', 'invoice_customer_status')
      AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = format('%I', i.indexname)::regclass)
  LOOP EXECUTE format('DROP INDEX %I', r.indexname); END LOOP;
END $$;
